1	/**
2	 * Washer-world materials: procedural perforated magenta metal (round holes for drums, circumferential
3	 * slots for tunnels), thick reflective gold, chrome, glass — all PBR (MeshStandardMaterial) so they pick
4	 * up the candy PMREM environment, with shader patches for the perforations and glow.
5	 */
6	import * as THREE from 'three';
7	
8	export interface PerforatedOptions {
9	  /** base metal colour */
10	  color?: THREE.ColorRepresentation;
11	  /** colour of the hole interiors */
12	  holeColor?: THREE.ColorRepresentation;
13	  /** 0 = round holes (drum), 1 = slots elongated along u (tunnel rings) */
14	  slot?: number;
15	  /** pattern repeats: holes around u (per 0..1) and per uv-unit along v */
16	  repeatU?: number;
17	  repeatV?: number;
18	  /** hole size relative to its cell (0..1) */
19	  holeSize?: number;
20	  emissive?: THREE.ColorRepresentation;
21	  emissiveIntensity?: number;
22	  metalness?: number;
23	  roughness?: number;
24	  side?: THREE.Side;
25	  /** bright stripe highlights running along v (tunnel light streaks) */
26	  streaks?: number;
27	  /** number of procedural lengthwise streaks around u (default 9) */
28	  streakCount?: number;
29	  /**
30	   * explicit slot half-size in CELL units [along u, along v] (overrides holeSize/slot); the cell is
31	   * 1/repeatU of the circumference by 1/repeatV along the tube, so world proportions follow from both
32	   */
33	  slotHalf?: [number, number];
34	  /** stagger every other slot row by half a cell (default true) */
35	  stagger?: boolean;
36	  /** pattern offset along v in cells (aligns slot rows between the ring bands) */
37	  offsetV?: number;
38	  /**
39	   * Washer-tube upgrade (05–07): pressed-metal corrugation + bevelled slot lips perturb the normal so
40	   * the glossy metal catches light around every slot (refs 05–07). Height amplitudes in world units.
41	   */
42	  relief?: { corrugation: number; bevel: number; bevelWidth?: number };
43	  /** emissive glow colour hugging every hole edge (refs: hot-pink glowing slot outlines) */
44	  rimColor?: THREE.ColorRepresentation;
45	  rimStrength?: number;
46	  /** warm "light at the end of the tunnel": emissive that grows with view distance */
47	  farGlow?: FarGlow;
48	  /** dedicated reflection environment (e.g. washerTubeEnv()) instead of scene.environment */
49	  envMap?: THREE.Texture | null;
50	  envMapIntensity?: number;
51	}
52	
53	export interface FarGlow {
54	  color: THREE.ColorRepresentation; near: number; far: number; strength: number;
55	  /** optional mid-distance tint of the metal colour (refs: walls turn violet deeper in the tunnel) */
56	  mid?: { color: THREE.ColorRepresentation; near: number; far: number; amount: number };
57	}
58	
59	/** GLSL for the distance glow, shared by the tube wall, rings and lids */
60	const FAR_GLOW_PARS = `uniform vec3 uFarGlowColor; uniform vec3 uFarGlowRange; uniform vec3 uMidTint; uniform vec3 uMidRange;
61	float farGlowK(){ return uFarGlowRange.z * smoothstep(uFarGlowRange.x, uFarGlowRange.y, length(vViewPosition)); }
62	float midTintK(){ return uMidRange.z * smoothstep(uMidRange.x, uMidRange.y, length(vViewPosition)); }`;
63	/** `solid` = 0 inside perforation holes (they stay dark), 1 on metal */
64	const FAR_GLOW_APPLY = (solid = '1.0') => `{ float sol = ${solid}; float mt = midTintK() * sol; diffuseColor.rgb = mix(diffuseColor.rgb, uMidTint, mt); totalEmissiveRadiance *= 1.0 - mt * 0.5;
65	  float fg = farGlowK(); diffuseColor.rgb = mix(diffuseColor.rgb, uFarGlowColor, min(1.0, fg * 0.5) * sol); totalEmissiveRadiance += uFarGlowColor * fg * mix(0.35, 1.0, sol); }`;
66	
67	function farGlowUniforms(g: FarGlow) {
68	  return {
69	    uFarGlowColor: { value: new THREE.Color(g.color) },
70	    uFarGlowRange: { value: new THREE.Vector3(g.near, g.far, g.strength) },
71	    uMidTint: { value: new THREE.Color(g.mid?.color ?? '#ffffff') },
72	    uMidRange: { value: new THREE.Vector3(g.mid?.near ?? 0, g.mid?.far ?? 1, g.mid?.amount ?? 0) },
73	  };
74	}
75	
76	/**
77	 * Adds the warm distance glow to any MeshStandardMaterial (rings, lids). The far end of the tube melts
78	 * into a bright warm vanishing point like refs 05/07 without adding scene lights (mobile-friendly).
79	 */
80	export function withFarGlow<T extends THREE.MeshStandardMaterial>(mat: T, g: FarGlow, key: string): T {
81	  const uniforms = farGlowUniforms(g);
82	  const prev = mat.onBeforeCompile;
83	  mat.onBeforeCompile = (shader, r) => {
84	    prev.call(mat, shader, r);
85	    Object.assign(shader.uniforms, uniforms);
86	    shader.fragmentShader = shader.fragmentShader
87	      .replace('#include <common>', '#include <common>\n' + FAR_GLOW_PARS)
88	      .replace(
89	        '#include <emissivemap_fragment>',
90	        `#include <emissivemap_fragment>
91	${FAR_GLOW_APPLY()}`,
92	      );
93	  };
94	  const prevKey = mat.customProgramCacheKey.bind(mat);
95	  mat.customProgramCacheKey = () => prevKey() + '|fg-' + key;
96	  mat.userData.farGlow = uniforms;
97	  return mat;
98	}
99	
100	/**
101	 * Analytic strip lights for the washer tubes (refs 05–07). Narrow light strips run the full length of
102	 * the tunnel at evenly spaced angles around its axis. Their radiance depends only on the azimuth of the
103	 * reflected view ray around the LOCAL tube axis, so (unlike a cube map, whose meridians pinch together
104	 * and blur at the pole every grazing wall reflection looks into) they stay crisp at any distance and
105	 * follow the tube through the 06 arch and the 07 plunge. The term is added to the IBL radiance, so the
106	 * normal PBR BRDF weights it: glossy magenta panels get lengthwise white-pink streaks, every gold band
107	 * gets evenly spaced "marquee" spots, and both line up radially like in the reference.
108	 * Axis source: 'attribute' = per-vertex `tubeAxis`/`tubeUp` (buildTubeGeometry({ axisAttr: true })),
109	 * 'instance' = local Z (axis) / local Y (up) of each instance matrix (rings, lids).
110	 */
111	export interface TubeStrips {
112	  count: number;
113	  /** angular half-width of one strip (radians, before roughness widening) */
114	  width: number;
115	  intensity: number;
116	  color: THREE.ColorRepresentation;
117	  /** brightness of every other strip (default 0.7) */
118	  alt?: number;
119	}
120	
121	export function withTubeStrips<T extends THREE.MeshStandardMaterial>(mat: T, s: TubeStrips, source: 'attribute' | 'instance', key: string): T {
122	  const uniforms = {
123	    uStripColor: { value: new THREE.Color(s.color).multiplyScalar(s.intensity) },
124	    uStripP: { value: new THREE.Vector4(s.count, s.width, 0, s.alt ?? 0.7) },
125	  };
126	  const prev = mat.onBeforeCompile;
127	  mat.onBeforeCompile = (shader, r) => {
128	    prev.call(mat, shader, r);
129	    Object.assign(shader.uniforms, uniforms);
130	    const axis = source === 'instance'
131	      ? `vTubeAxis = normalize((viewMatrix * modelMatrix * instanceMatrix * vec4(0.0, 0.0, 1.0, 0.0)).xyz);
132	vTubeUp = normalize((viewMatrix * modelMatrix * instanceMatrix * vec4(0.0, 1.0, 0.0, 0.0)).xyz);`
133	      : `vTubeAxis = normalize((viewMatrix * modelMatrix * vec4(tubeAxis, 0.0)).xyz);
134	vTubeUp = normalize((viewMatrix * modelMatrix * vec4(tubeUp, 0.0)).xyz);`;
135	    shader.vertexShader = shader.vertexShader
136	      .replace('#include <common>', `#include <common>
137	varying vec3 vTubeAxis; varying vec3 vTubeUp;
138	${source === 'attribute' ? 'attribute vec3 tubeAxis; attribute vec3 tubeUp;' : ''}`)
139	      .replace('#include <project_vertex>', `#include <project_vertex>
140	${axis}`);
141	    shader.fragmentShader = shader.fragmentShader
142	      .replace('#include <common>', `#include <common>
143	varying vec3 vTubeAxis; varying vec3 vTubeUp; uniform vec3 uStripColor; uniform vec4 uStripP;
144	vec3 tubeStripRadiance(vec3 V, vec3 N, float rough){
145	  vec3 R = reflect(-V, N);
146	  vec3 A = normalize(vTubeAxis);
147	  vec3 E1 = normalize(vTubeUp - A * dot(vTubeUp, A));
148	  vec3 E2 = cross(A, E1);
149	  vec3 P = R - A * dot(R, A);
150	  float pl = length(P);
151	  float t = atan(dot(P, E2), dot(P, E1)) * uStripP.x / 6.2831853; // strip index space
152	  float fw = min(fwidth(t), fwidth(fract(t + 0.5)));
153	  float w0 = uStripP.y * uStripP.x / 6.2831853;            // half-width in pitch units
154	  float w = w0 + rough * rough * 1.5 + fw * 0.6;
155	  float dA = fract(t + 0.5) - 0.5;
156	  float k = exp(-dA * dA / (w * w)) * mix(1.0, w0 / w, 0.75);
157	  k *= mod(floor(t + 0.5), 2.0) > 0.5 ? uStripP.w : 1.0;
158	  return uStripColor * k * smoothstep(0.02, 0.12, pl);
159	}`)
160	      .replace('#include <lights_fragment_maps>', `#include <lights_fragment_maps>
161	#if defined( RE_IndirectSpecular )
162	radiance += tubeStripRadiance(geometryViewDir, geometryNormal, material.roughness);
163	#endif`);
164	  };
165	  const prevKey = mat.customProgramCacheKey.bind(mat);
166	  mat.customProgramCacheKey = () => prevKey() + '|strips-' + source + '-' + key;
167	  mat.userData.tubeStrips = uniforms;
168	  return mat;
169	}
170	
171	export function perforatedMetal(o: PerforatedOptions = {}): THREE.MeshStandardMaterial {
172	  const mat = new THREE.MeshStandardMaterial({
173	    color: o.color ?? '#d13fd6',
174	    metalness: o.metalness ?? 0.72,
175	    roughness: o.roughness ?? 0.26,
176	    emissive: new THREE.Color(o.emissive ?? '#9a1fa8'),
177	    emissiveIntensity: o.emissiveIntensity ?? 0.26,
178	    side: o.side ?? THREE.BackSide,
179	    envMapIntensity: o.envMapIntensity ?? 1.0,
180	  });
181	  if (o.envMap) mat.envMap = o.envMap;
182	  const relief = o.relief;
183	  const uniforms = {
184	    uHoleColor: { value: new THREE.Color(o.holeColor ?? '#2b0640') },
185	    uSlot: { value: o.slot ?? 1 },
186	    uRepeat: { value: new THREE.Vector2(o.repeatU ?? 64, o.repeatV ?? 1.2) },
187	    uHoleSize: { value: o.holeSize ?? 0.42 },
188	    uStreaks: { value: o.streaks ?? 0.35 },
189	    uStreakN: { value: o.streakCount ?? 9 },
190	    uSlotHalf: { value: new THREE.Vector2(o.slotHalf?.[0] ?? -1, o.slotHalf?.[1] ?? -1) },
191	    uStagger: { value: o.stagger === false ? 0 : 0.5 },
192	    uOffsetV: { value: o.offsetV ?? 0 },
193	    uRelief: { value: new THREE.Vector3(relief?.corrugation ?? 0, relief?.bevel ?? 0, relief?.bevelWidth ?? 0.09) },
194	    uRimColor: { value: new THREE.Color(o.rimColor ?? '#ffd1ff') },
195	    uRimStrength: { value: o.rimStrength ?? 0.55 },
196	    ...(o.farGlow ? farGlowUniforms(o.farGlow) : {}),
197	  };
198	  const defines: Record<string, string> = {};
199	  if (relief) defines.PERF_RELIEF = '';
200	  if (o.farGlow) defines.PERF_FARGLOW = '';
201	  mat.defines = defines;
202	  mat.userData.perfUniforms = uniforms;
203	  mat.onBeforeCompile = (shader) => {
204	    Object.assign(shader.uniforms, uniforms);
205	    shader.vertexShader = shader.vertexShader
206	      .replace('#include <common>', '#include <common>\nvarying vec2 vPerfUv;')
207	      .replace('#include <uv_vertex>', '#include <uv_vertex>\nvPerfUv = uv;');
208	    shader.fragmentShader = shader.fragmentShader
209	      .replace(
210	        '#include <common>',
211	        `#include <common>
212	varying vec2 vPerfUv;
213	uniform vec3 uHoleColor; uniform float uSlot; uniform vec2 uRepeat; uniform float uHoleSize; uniform float uStreaks;
214	uniform vec3 uRelief; uniform vec3 uRimColor; uniform float uRimStrength; uniform float uStreakN; uniform vec2 uSlotHalf; uniform float uStagger; uniform float uOffsetV;
215	#ifdef PERF_FARGLOW
216	${FAR_GLOW_PARS}
217	#endif
218	vec2 perfCell(vec2 uv){
219	  vec2 g = uv * uRepeat;
220	  g.y += uOffsetV;
221	  g.x += mod(floor(g.y), 2.0) * uStagger;   // staggered rows
222	  return g;
223	}
224	// signed distance to the slot/hole (cell units, <0 inside)
225	float perfSdf(vec2 g){
226	  vec2 f = fract(g) - 0.5;
227	  vec2 hs = uSlotHalf.x > 0.0 ? uSlotHalf : mix(vec2(uHoleSize*0.5), vec2(uHoleSize*0.62, uHoleSize*0.24), uSlot);
228	  vec2 q = abs(f) - hs + min(hs.x, hs.y);
229	  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - min(hs.x, hs.y);
230	}
231	float perfMask(vec2 uv, out float rim){
232	  vec2 g = perfCell(uv);
233	  vec2 f = fract(g) - 0.5;
234	  float d = perfSdf(g);
235	  float aa = fwidth(d) * 1.2 + 1e-4;
236	  rim = smoothstep(0.06, 0.0, abs(d - 0.02)) * step(0.0, f.y);  // light catching the lower lip
237	  return 1.0 - smoothstep(-aa, aa, d); // 1 inside hole
238	}
239	#ifdef PERF_RELIEF
240	// pressed-metal relief (world units): shallow grooves along each slot row, bevelled lips into every slot
241	float perfHeight(vec2 g){
242	  float fy = fract(g.y) - 0.5;
243	  float d = perfSdf(g);
244	  return -cos(6.2831853 * fy) * uRelief.x + (smoothstep(0.0, uRelief.z, d) - 1.0) * uRelief.y;
245	}
246	#endif`,
247	      )
248	      .replace(
249	        '#include <color_fragment>',
250	        `#include <color_fragment>
251	float perfRim; float perfHole = perfMask(vPerfUv, perfRim);
252	float streak = pow(0.5 + 0.5 * sin(vPerfUv.x * 6.2831 * uStreakN + 1.3), 18.0) * uStreaks;
253	diffuseColor.rgb = mix(diffuseColor.rgb * (1.0 + streak), uHoleColor, perfHole);`,
254	      )
255	      .replace(
256	        '#include <normal_fragment_maps>',
257	        `#include <normal_fragment_maps>
258	#ifdef PERF_RELIEF
259	{
260	  // analytic relief gradient in uv space → view space via the screen-derivative cotangent frame
261	  vec2 g = perfCell(vPerfUv);
262	  float e = 0.015;
263	  float h0 = perfHeight(g);
264	  vec2 dHdg = vec2(perfHeight(g + vec2(e, 0.0)) - h0, perfHeight(g + vec2(0.0, e)) - h0) / e;
265	  vec2 dHduv = dHdg * uRepeat;
266	  vec3 dp1 = dFdx(-vViewPosition), dp2 = dFdy(-vViewPosition);
267	  vec2 duv1 = dFdx(vPerfUv), duv2 = dFdy(vPerfUv);
268	  vec3 dp2perp = cross(dp2, normal), dp1perp = cross(normal, dp1);
269	  float det = dot(dp1, dp2perp);
270	  if (abs(det) > 1e-12) {
271	    vec3 gradU = (dp2perp * duv1.x + dp1perp * duv2.x) / det;
272	    vec3 gradV = (dp2perp * duv1.y + dp1perp * duv2.y) / det;
273	    // fade the relief out where the pattern gets sub-pixel (prevents sparkle in the distance)
274	    float px = max(length(fwidth(g)), 1e-4);
275	    float lod = 1.0 - smoothstep(0.18, 0.45, px);
276	    normal = normalize(normal - (dHduv.x * gradU + dHduv.y * gradV) * lod);
277	  }
278	}
279	#endif`,
280	      )
281	      .replace(
282	        '#include <metalnessmap_fragment>',
283	        `#include <metalnessmap_fragment>
284	metalnessFactor *= (1.0 - perfHole);`,
285	      )
286	      .replace(
287	        '#include <roughnessmap_fragment>',
288	        `#include <roughnessmap_fragment>
289	roughnessFactor = mix(roughnessFactor, 0.9, perfHole);`,
290	      )
291	      .replace(
292	        '#include <emissivemap_fragment>',
293	        `#include <emissivemap_fragment>
294	totalEmissiveRadiance = totalEmissiveRadiance * (1.0 - perfHole) + uRimColor * perfRim * uRimStrength * (1.0 - perfHole) + vec3(1.0,0.9,1.0) * streak * 0.6;
295	#ifdef PERF_FARGLOW
296	${FAR_GLOW_APPLY('1.0 - perfHole')}
297	#endif`,
298	      );
299	  };
300	  mat.customProgramCacheKey = () => 'perf-v3' + (relief ? '-r' : '') + (o.farGlow ? '-g' : '');
301	  return mat;
302	}
303	
304	/**
305	 * Reflection environment for the washer tubes (05–07): an HDR cube of hot-pink / magenta / violet with
306	 * pink-white strip lights around the tube and a warm gold-white glow down the tunnel (-Z), so the glossy
307	 * walls read rich saturated magenta (the shared candy studio has a cyan panel that turned them sky-blue).
308	 * Built from half-float DataTextures; three converts it to PMREM on first use (no renderer needed here).
309	 */
310	const tubeEnvs: Partial<Record<'wall' | 'gold', THREE.CubeTexture>> = {};
311	/** variant 'gold': same tunnel lighting seen by polished gold (warm-white strips, amber base) so rings and
312	 *  lids read clean orange-gold with yellow-white highlights instead of salmon (gold × magenta). */
313	export function washerTubeEnv(variant: 'wall' | 'gold' = 'wall'): THREE.CubeTexture {
314	  const cached = tubeEnvs[variant];
315	  if (cached) return cached;
316	  const isGold = variant === 'gold';
317	  const N = 128;
318	  const dir = new THREE.Vector3();
319	  const col = new THREE.Color();
320	  const faces: THREE.DataTexture[] = [];
321	  // cube face orientation (same convention as WebGL cube maps)
322	  const faceDir = (f: number, a: number, b: number) => {
323	    switch (f) {
324	      case 0: return dir.set(1, -b, -a);
325	      case 1: return dir.set(-1, -b, a);
326	      case 2: return dir.set(a, 1, b);
327	      case 3: return dir.set(a, -1, -b);
328	      case 4: return dir.set(a, -b, 1);
329	      default: return dir.set(-a, -b, -1);
330	    }
331	  };
332	  // Smooth base only: the strip lights are analytic (withTubeStrips), because grazing wall reflections all
333	  // look almost straight down the tunnel, where a cube map's meridian strips pinch together and blur.
334	  const cBaseTop = isGold ? new THREE.Color(0.62, 0.24, 0.07) : new THREE.Color(0.62, 0.05, 0.42);
335	  const cBaseLow = isGold ? new THREE.Color(0.3, 0.09, 0.05) : new THREE.Color(0.22, 0.05, 0.55);
336	  const radiance = (d: THREE.Vector3, out: THREE.Color) => {
337	    const up = d.y;
338	    // base: magenta above, violet toward the floor
339	    out.copy(cBaseTop).lerp(cBaseLow, THREE.MathUtils.smoothstep(-up, -0.3, 0.9));
340	    // gold only: a warm yellow-white core at the very end of the tunnel (-Z) so far bands glow like the VP
341	    const ahead = Math.max(0, -d.z);
342	    if (isGold) {
343	      const hot = Math.pow(ahead, 60), wide = Math.pow(ahead, 6);
344	      out.r += 2.4 * hot + 0.3 * wide; out.g += 2.0 * hot + 0.16 * wide; out.b += 1.0 * hot + 0.04 * wide;
345	    } else {
346	      const wide = Math.pow(ahead, 6);
347	      out.r += 0.05 * wide; out.g += 0.02 * wide; out.b += 0.25 * wide; // violet haze down the tunnel
348	    }
349	    return out;
350	  };
351	  for (let f = 0; f < 6; f++) {
352	    const data = new Uint16Array(N * N * 4);
353	    for (let y = 0; y < N; y++) {
354	      for (let x = 0; x < N; x++) {
355	        const a = ((x + 0.5) / N) * 2 - 1, b = ((y + 0.5) / N) * 2 - 1;
356	        radiance(faceDir(f, a, b).normalize(), col);
357	        const i = (y * N + x) * 4;
358	        data[i] = THREE.DataUtils.toHalfFloat(col.r);
359	        data[i + 1] = THREE.DataUtils.toHalfFloat(col.g);
360	        data[i + 2] = THREE.DataUtils.toHalfFloat(col.b);
361	        data[i + 3] = THREE.DataUtils.toHalfFloat(1);
362	      }
363	    }
364	    const t = new THREE.DataTexture(data, N, N, THREE.RGBAFormat, THREE.HalfFloatType);
365	    t.colorSpace = THREE.LinearSRGBColorSpace;
366	    t.needsUpdate = true;
367	    faces.push(t);
368	  }
369	  const cube = new THREE.CubeTexture(faces as unknown as HTMLImageElement[]);
370	  cube.type = THREE.HalfFloatType;
371	  cube.format = THREE.RGBAFormat;
372	  cube.colorSpace = THREE.LinearSRGBColorSpace;
373	  cube.minFilter = THREE.LinearFilter;
374	  cube.magFilter = THREE.LinearFilter;
375	  cube.generateMipmaps = false;
376	  cube.needsUpdate = true;
377	  tubeEnvs[variant] = cube;
378	  return cube;
379	}
380	
381	/**
382	 * "Light at the end of the tunnel" (ref 05): a warm radial glow filling the tube cross-section at the end
383	 * of the straight 05 current. Opaque yellow-white core → gold → warm magenta → transparent rim, HDR so the
384	 * core blooms a little. It fades with the CAMERA distance to its own centre: full beyond `fade.y`, gone
385	 * inside `fade.x` (the rider approaching 06 sees the arch hall open up) and again beyond `fade.w` (far
386	 * stages never see it). Unit circle in local XY, facing +Z.
387	 */
388	export function tunnelEndGlowMaterial(fade = new THREE.Vector4(14, 30, 95, 120)): THREE.ShaderMaterial {
389	  return new THREE.ShaderMaterial({
390	    uniforms: {
391	      uFade: { value: fade },
392	      uCore: { value: new THREE.Color(3.4, 3.0, 2.0) },
393	      uGold: { value: new THREE.Color(2.3, 1.35, 0.32) },
394	      uWarm: { value: new THREE.Color(1.05, 0.34, 0.3) },
395	      uRim: { value: new THREE.Color(0.36, 0.05, 0.42) },
396	    },
397	    vertexShader: /* glsl */ `varying vec2 vUv; varying float vFade; uniform vec4 uFade;
398	      void main(){
399	        vUv = uv;
400	        float d = distance(cameraPosition, (modelMatrix * vec4(0.0, 0.0, 0.0, 1.0)).xyz);
401	        vFade = smoothstep(uFade.x, uFade.y, d) * (1.0 - smoothstep(uFade.z, uFade.w, d));
402	        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
403	      }`,
404	    fragmentShader: /* glsl */ `varying vec2 vUv; varying float vFade; uniform vec3 uCore; uniform vec3 uGold; uniform vec3 uWarm; uniform vec3 uRim;
405	      void main(){
406	        float r = length(vUv - 0.5) * 2.0;
407	        vec3 c = mix(uRim, uWarm, smoothstep(0.92, 0.5, r));
408	        c = mix(c, uGold, smoothstep(0.6, 0.18, r));
409	        c = mix(c, uCore, smoothstep(0.26, 0.0, r));
410	        float a = (1.0 - smoothstep(0.7, 1.0, r)) * vFade;
411	        if (a < 0.003) discard;
412	        gl_FragColor = vec4(c, a);
413	        #include <tonemapping_fragment>
414	        #include <colorspace_fragment>
415	      }`,
416	    transparent: true,
417	    depthWrite: false,
418	    fog: false,
419	  });
420	}
