422	export function gold(opts: { roughness?: number; emissive?: number; color?: THREE.ColorRepresentation } = {}): THREE.MeshStandardMaterial {
423	  return new THREE.MeshStandardMaterial({
424	    color: opts.color ?? '#ffcf4d',
425	    metalness: 1,
426	    roughness: opts.roughness ?? 0.2,
427	    emissive: new THREE.Color('#c98a00'),
