433	/** gold with ribbed "ring pipe" bands along v (scene 04 tunnel) */
434	export function goldRibbed(repeatV = 1.6): THREE.MeshStandardMaterial {
435	  const m = gold({ roughness: 0.18, emissive: 0.5 });
436	  m.side = THREE.BackSide;
437	  const uniforms = { uRibs: { value: repeatV } };
438	  m.onBeforeCompile = (shader) => {
439	    Object.assign(shader.uniforms, uniforms);
440	    shader.vertexShader = shader.vertexShader
441	      .replace('#include <common>', '#include <common>\nvarying vec2 vRibUv;')
442	      .replace('#include <uv_vertex>', '#include <uv_vertex>\nvRibUv = uv;');
443	    shader.fragmentShader = shader.fragmentShader
444	      .replace('#include <common>', '#include <common>\nvarying vec2 vRibUv; uniform float uRibs;')
445	      .replace(
446	        '#include <color_fragment>',
447	        `#include <color_fragment>
448	float rp = fract(vRibUv.y * uRibs);
449	diffuseColor.rgb *= 0.72 + 0.42 * smoothstep(0.0, 0.5, rp) * smoothstep(1.0, 0.5, rp);`,
450	      )
451	      .replace(
452	        '#include <emissivemap_fragment>',
453	        `#include <emissivemap_fragment>
454	float edge = smoothstep(0.85, 1.0, fract(vRibUv.y * uRibs));
455	totalEmissiveRadiance += vec3(1.0, 0.86, 0.5) * edge * 0.9;`,
456	      );
457	  };
458	  m.customProgramCacheKey = () => 'goldrib-v1';
459	  return m;
460	}
