15	export interface Environment {
16	  group: THREE.Group;
17	  update(time: number, dt: number): void;
18	  doorA: THREE.Object3D; // hinge pivot (rotation.y opens)
19	  doorC: THREE.Object3D;
20	  roomA: LaundryRoom & { anchor: THREE.Object3D };
21	  roomC: LaundryRoom & { anchor: THREE.Object3D };
22	  towel: TowelMesh; // on the chamber platform (08–11)
23	  drumTowel: TowelMesh; // bundle wrapped around Benny in drum A (01–02)
24	  laundry: { sock: THREE.Object3D; shirt: THREE.Object3D };
25	  /** groups toggled per scene for performance */
