36	export function buildEnvironment(course: Course): Environment {
37	  const root = new THREE.Group();
38	  root.name = 'washer_world';
39	  const zones = {
40	    drumA: new THREE.Group(),
41	    basin: new THREE.Group(),
42	    tubes: new THREE.Group(),
43	    chamber: new THREE.Group(),
44	  };
45	  Object.entries(zones).forEach(([k, g]) => { g.name = 'zone_' + k; root.add(g); });
46	  const goldMat = gold();
47	  const goldSoft = gold({ roughness: 0.3, emissive: 0.3 });
48	  const chromeMat = chrome();
49	  const animated: ((t: number, dt: number) => void)[] = [];
50	
51	  // =====================================================================================
52	  // Drum A (01–02)
53	  // =====================================================================================
54	  const dA = WORLD.drumA;
55	  const drumLen = dA.zDoor - dA.zBack;
56	  const drumGeo = new THREE.CylinderGeometry(dA.radius, dA.radius, drumLen, 96, 24, true);
57	  drumGeo.rotateX(Math.PI / 2);
58	  drumGeo.translate(0, 0, (dA.zDoor + dA.zBack) / 2);
59	  const drumMat = perforatedMetal({ color: '#f04fc8', emissive: '#c22aa6', emissiveIntensity: 0.3, slot: 0, repeatU: 54, repeatV: 15, holeSize: 0.44, streaks: 0.15 });
60	  zones.drumA.add(new THREE.Mesh(drumGeo, drumMat));
61	  // back wall with the drain opening
62	  const backShape = new THREE.Shape();
63	  backShape.absarc(0, 0, dA.radius, 0, Math.PI * 2, false);
64	  const drainHole = new THREE.Path();
65	  drainHole.absarc(-0.3, -3.05, 1.85, 0, Math.PI * 2, true);
66	  backShape.holes.push(drainHole);
67	  const backGeo = new THREE.ShapeGeometry(backShape, 48);
68	  backGeo.translate(0, 0, dA.zBack);
69	  const backMat = perforatedMetal({ color: '#e544c4', slot: 0, repeatU: 9, repeatV: 9, holeSize: 0.4, side: THREE.DoubleSide, streaks: 0 });
70	  zones.drumA.add(new THREE.Mesh(backGeo, backMat));
71	  // front wall annulus
72	  const frontShape = new THREE.Shape();
73	  frontShape.absarc(0, 0, dA.radius, 0, Math.PI * 2, false);
74	  const doorHole = new THREE.Path();
75	  doorHole.absarc(0, 0, dA.doorRadius, 0, Math.PI * 2, true);
76	  frontShape.holes.push(doorHole);
77	  const frontGeo = new THREE.ShapeGeometry(frontShape, 64);
78	  frontGeo.translate(0, 0, dA.zDoor);
79	  zones.drumA.add(new THREE.Mesh(frontGeo, perforatedMetal({ color: '#f15ccd', slot: 0, repeatU: 8, repeatV: 8, holeSize: 0.0, side: THREE.DoubleSide, streaks: 0, metalness: 0.85, roughness: 0.18 })));
80	  // gold door ring (thick) + chrome inner lip
81	  const ringA = new THREE.Mesh(new THREE.TorusGeometry(dA.doorRadius + 0.35, 0.48, 24, 96), goldMat);
82	  ringA.position.set(0, 0, dA.zDoor - 0.1);
83	  zones.drumA.add(ringA);
84	  const ringA2 = new THREE.Mesh(new THREE.TorusGeometry(dA.doorRadius + 1.15, 0.22, 16, 96), goldSoft);
85	  ringA2.position.set(0, 0, dA.zDoor - 0.15);
86	  zones.drumA.add(ringA2);
87	  // lifters (gold baffles)
88	  for (const ang of [52, 128, 270]) {
89	    const a = THREE.MathUtils.degToRad(ang);
90	    const lifter = new THREE.Mesh(new RoundedBoxGeometry(1.5, 1.1, drumLen - 1.6, 4, 0.5), goldMat);
91	    lifter.position.set(Math.cos(a) * (dA.radius - 0.45), Math.sin(a) * (dA.radius - 0.45), (dA.zDoor + dA.zBack) / 2 - 0.3);
92	    lifter.rotation.z = a + Math.PI / 2;
93	    zones.drumA.add(lifter);
94	  }
95	  // washer door A (hinged on the left seen from the room: pivot at x=-r)
96	  const doorA = new THREE.Group();
97	  doorA.name = 'doorA_pivot';
98	  doorA.position.set(-(dA.doorRadius + 0.6), 0, dA.zDoor + 0.55);
99	  const doorAInner = new THREE.Group();
100	  doorAInner.position.set(dA.doorRadius + 0.6, 0, 0);
101	  const doorRingA = new THREE.Mesh(new THREE.TorusGeometry(dA.doorRadius + 0.2, 0.42, 20, 80), chromeMat);
102	  const doorGlassA = new THREE.Mesh(new THREE.CircleGeometry(dA.doorRadius + 0.05, 48), glass('#e8f0ff', 0.1));
103	  doorAInner.add(doorRingA, doorGlassA);
104	  doorA.add(doorAInner);
105	  zones.drumA.add(doorA);
106	  // laundry room A outside the door
107	  const roomA = buildLaundryRoom({ floorDrop: 11, palette: 'warm' });
108	  const anchorA = new THREE.Group();
109	  anchorA.position.set(0, 0, dA.zDoor + 0.8);
110	  anchorA.add(roomA.group);
111	  zones.drumA.add(anchorA);
112	  // floating laundry: blue striped sock + pink star T-shirt
113	  const sock = buildSock();
114	  const shirt = buildShirt();
115	  zones.drumA.add(sock, shirt);
116	  // towel bundle around Benny
117	  const drumTowel = buildTowel();
118	  drumTowel.setBundle(1);
119	  zones.drumA.add(drumTowel.mesh);
120	  // chute from drum A drain to the basin rim
121	  // the chute begins exactly where the course passes through the drum's back wall
122	  let sChute0 = course.marks['02_drain'] - 3;
123	  while (course.sample(sChute0).pos.z > dA.zBack + 0.3 && sChute0 < course.stage('03').s0) sChute0 += 0.1;
124	  const sChute1 = course.stage('03').s0 + 0.3;
125	  const chutePath = courseTubePath(course, () => 2.25, 0.55);
126	  const chute = new THREE.Mesh(
127	    buildTubeGeometry(chutePath, sChute0, sChute1, { radial: 36, step: 0.5, vScale: 1 }),
128	    perforatedMetal({ color: '#e94ad0', slot: 0, repeatU: 22, repeatV: 1.6, holeSize: 0.38 }),
129	  );
130	  zones.drumA.add(chute);
131	  zones.drumA.add(buildRings(chutePath, sChute0 + 1.5, sChute1 - 1, 3.2, goldMat, { tube: 0.09 }));
132	
133	  // =====================================================================================
134	  // Whirlpool basin room (03) + backdrop shared with 04
135	  // =====================================================================================
136	  const B = WORLD.basin;
137	  const prof: THREE.Vector2[] = [];
138	  for (let i = 0; i <= 40; i++) {
139	    const r = B.drainRadius * 1.04 + (B.rimRadius + 0.4 - B.drainRadius * 1.04) * (i / 40);
140	    prof.push(new THREE.Vector2(r, funnelY(r) - 0.45));
141	  }
142	  const funnelGeo = new THREE.LatheGeometry(prof, 96);
143	  funnelGeo.translate(B.center.x, 0, B.center.z);
144	  zones.basin.add(new THREE.Mesh(funnelGeo, perforatedMetal({ color: '#e04fd0', slot: 0, repeatU: 60, repeatV: 22, holeSize: 0.3, side: THREE.DoubleSide, streaks: 0 })));
145	  // thick gold drain lip + inner ring (ref 03: concentric gold rings inside the drain)
146	  for (const [rr, tt, dy] of [[B.drainRadius + 0.15, 0.42, 0.1], [B.drainRadius - 0.55, 0.22, -0.9]] as const) {
147	    const lip = new THREE.Mesh(new THREE.TorusGeometry(rr, tt, 18, 96), goldMat);
148	    lip.rotation.x = Math.PI / 2;
149	    lip.position.set(B.center.x, funnelY(B.drainRadius) + dy, B.center.z);
150	    zones.basin.add(lip);
151	  }
152	  const rim = new THREE.Mesh(new THREE.TorusGeometry(B.rimRadius + 0.5, 0.75, 24, 128), goldMat);
153	  rim.rotation.x = Math.PI / 2;
154	  rim.position.set(B.center.x, B.rimY + 0.25, B.center.z);
155	  zones.basin.add(rim);
156	  const rim2 = new THREE.Mesh(new THREE.TorusGeometry(B.rimRadius + 2.1, 0.35, 16, 128), goldSoft);
157	  rim2.rotation.x = Math.PI / 2;
158	  rim2.position.set(B.center.x, B.rimY + 0.35, B.center.z);
159	  zones.basin.add(rim2);
160	  // glossy pink deck around the basin
161	  const deckShape = new THREE.Shape();
162	  deckShape.moveTo(-34, -34); deckShape.lineTo(34, -34); deckShape.lineTo(34, 30); deckShape.lineTo(-34, 30); deckShape.lineTo(-34, -34);
163	  const deckHole = new THREE.Path();
164	  deckHole.absarc(0, 0, B.rimRadius + 0.4, 0, Math.PI * 2, true);
165	  deckShape.holes.push(deckHole);
166	  const deck = new THREE.Mesh(new THREE.ShapeGeometry(deckShape, 64), new THREE.MeshStandardMaterial({ color: '#f36fd6', metalness: 0.5, roughness: 0.2, emissive: '#c43bb0', emissiveIntensity: 0.35, side: THREE.DoubleSide }));
167	  deck.rotation.x = -Math.PI / 2;
168	  deck.position.set(B.center.x, B.rimY + 0.3, B.center.z);
169	  zones.basin.add(deck);
170	  buildBasinBackdrop(zones.basin, goldMat, chromeMat);
171	
172	  // =====================================================================================
173	  // 04 gold ring pipe
174	  // =====================================================================================
175	  const s04 = course.stage('04').s0, s05 = course.stage('05').s0;
176	  const tubeR = (s: number) => course.prop('tube', s);
177	  // the pipe mouth is the drain hole itself: narrow at the lip, opening up as it dives
178	  // the ring tunnel starts just ahead of Benny on the open slide (ref 04), with a flared mouth
179	  const g0 = s04 + 5.0;
180	  const r04 = (s: number) => tubeR(s) + 1.8 * (1 - sm(g0, g0 + 6, s));
181	  const goldPath = courseTubePath(course, r04, 0.9);
182	  const goldPipe = new THREE.Mesh(buildTubeGeometry(goldPath, g0, s05, { radial: 56, step: 0.4 }), goldRibbed(1.25));
183	  zones.tubes.add(goldPipe);
184	  zones.tubes.add(buildRings(goldPath, g0 + 0.2, s05 - 1, 1.6, goldMat, { tube: 0.05, inset: 0.02 }));
185	  // big mouth rings at the drain
186	  for (let i = 0; i < 4; i++) {
187	    const s = g0 + 0.05 + i * 0.3;
188	    zones.tubes.add(buildRings(goldPath, s, s + 0.01, 1, goldMat, { tube: 0.07, extra: 0.4 + i * 0.22 }));
189	  }
190	
191	  // =====================================================================================
192	  // 05–07 perforated tubes (incl. the 06 arch hall and the full 07 plunge)
193	  // =====================================================================================
194	  const s08 = course.stage('08').s0;
195	  const pinkFlow = pinkFlowMaterial();
196	  // refs 05–07: rich saturated magenta→violet glossy pressed metal, dense glowing slot rows, warm light
197	  // far down the tunnel. Own reflection environment (no cyan studio panel) + correct inward normals.
198	  // hot magenta near → violet mid-tunnel → warm yellow-white core at the vanishing point
199	  const tubeGlow: FarGlow = { color: '#ffd08a', near: 48, far: 105, strength: 1.5 };
200	  const wallGlow: FarGlow = { ...tubeGlow, mid: { color: '#8a3cf0', near: 10, far: 42, amount: 0.55 } };
201	  const tubeEnv = washerTubeEnv('wall');
202	  const goldEnv = washerTubeEnv('gold');
203	  // 06/07 ring bays (unchanged): gold bands every 9 units, 4 circumferential slot rows per bay
204	  const ringSpacing = 9.0;
205	  const slotRowsPerBay = 4;
206	  // analytic strip lights along the tunnel (28 around: ref 05 shows ≈12–16 marquee spots per half-ring)
207	  const strips: TubeStrips = { count: 28, width: 0.022, intensity: 2.6, color: '#ffd9f6', alt: 0.65 };
208	  // glossy (low roughness → the strips stay crisp lengthwise streaks instead of a flat clipped sheen)
209	  const wallBase = {
210	    // pale pink F0: the saturation comes from the magenta/violet tube environment, so white strip lights
211	    // reflect as white-pink streaks (a saturated F0 turned them into clipped flat magenta)
212	    color: '#ffa8e8', emissive: '#3a0656', emissiveIntensity: 0.3, holeColor: '#0c0014',
213	    slot: 1, repeatU: 48, stagger: false,
214	    streaks: 0, metalness: 0.92, roughness: 0.1,
215	    relief: { corrugation: 0.05, bevel: 0.05, bevelWidth: 0.12 }, rimColor: '#ff5fe0', rimStrength: 0.9,
216	    envMap: tubeEnv, envMapIntensity: 1.0, farGlow: wallGlow,
217	  } as const;
218	  const perfTubeMat = perforatedMetal({ ...wallBase, repeatV: slotRowsPerBay / ringSpacing, slotHalf: [0.36, 0.12] });
219	  withTubeStrips(perfTubeMat, strips, 'attribute', 'wall');
220	  // straight-axis tunnel (05 → 07 incl. arch + plunge); the stream winds inside it
221	  const perfPath = straightTubePath(course, s05, s08, { window: 30, taper: 14, baseRadius: tubeR });
222	
223	  // ---- 05 current (ref 05): EVENLY spaced ring bays anchored to the 05 checkpoint camera ----
224	  // The camera rides `back` units behind Benny's checkpoint point; the first band sits `ring05Lead` ahead of
225	  // it, then one every `bay05` up to the end of the straight (the tube flares into the 06 hall at ≈ s06 − 6),
226	  // so the rings converge concentrically on the tunnel VP with a smooth perspective fall-off. If
227	  // path-camera moves the checkpoint or the camera distance, the bays follow automatically.
228	  const sCam05 = course.marks['05_crest'] - (STAGE_CAM['05']?.back ?? 6.4);
229	  const bay05 = 6.0, ring05Lead = 8.0;
230	  const sGlow05 = course.stage('06').s0 - 5.9; // warm "light at the end" just before the flare
231	  const rings05: number[] = [];
232	  for (let s = sCam05 + ring05Lead - Math.floor((sCam05 + ring05Lead - s05 - 2) / bay05) * bay05; s <= sGlow05 - 0.9; s += bay05) rings05.push(s);
233	  // 05 walls: 4 dark capsule-slot rows per 6-unit bay, centred between the bands (rows 1.5 apart),
234	  // slots ≈0.7 × 0.25 units laid along the circumference (ref 05 near slots ≈14 × 40 px)
235	  const slotPitch05 = bay05 / 4;
236	  const perf05Mat = perforatedMetal({
237	    ...wallBase, repeatV: 1 / slotPitch05, slotHalf: [0.35, 0.085],
238	    offsetV: 0.5 - ((((rings05[0] + slotPitch05 / 2) / slotPitch05) % 1) + 1) % 1,
239	  });
240	  withTubeStrips(perf05Mat, strips, 'attribute', 'wall05');
241	  const chunk = 40;
242	  const addWall = (a0: number, a1: number, mat: THREE.Material) => {
243	    for (let a = a0; a < a1 - 0.01; a += chunk) {
244	      const b = Math.min(a1, a + chunk + 0.6);
245	      zones.tubes.add(new THREE.Mesh(buildTubeGeometry(perfPath, a, b, { radial: 72, step: 0.6, frontNormals: true, axisAttr: true }), mat));
246	      // glossy magenta flow sheet lining the tube floor under the stream (refs 05/07 pink banks)
247	      zones.tubes.add(new THREE.Mesh(buildTubeGeometry(perfPath, a, b, { radial: 24, step: 0.8, arc: 1.9, inset: -0.12, vScale: 6, frontNormals: true }), pinkFlow.material));
248	    }
249	  };
250	  addWall(s05, sGlow05, perf05Mat);
251	  addWall(sGlow05, s08, perfTubeMat);
252	  // flat polished gold-copper ring bands at even spacing (ref 05: ≈10 concentric rings, double contour,
253	  // marquee highlight spots from the strip lights)
254	  const ringMat = withTubeStrips(withFarGlow(gold({ color: '#ffc890', roughness: 0.12, emissive: 0.16 }), tubeGlow, 'ring'), { ...strips, color: '#fff0c8', intensity: 3.2 }, 'instance', 'ring');
255	  ringMat.envMap = goldEnv;
256	  ringMat.envMapIntensity = 1.3;
257	  // 06/07 ring phase (unchanged positions s05 + 7.8 + 9k)
258	  const ringPhase = 7.8;
259	  const collar = { depth: 0.022, lip: 0.012, width: 1.1 };
260	  // gold junction collar 04→05 (slightly heavier)
261	  zones.tubes.add(buildRings(perfPath, s05 + 0.3, s05 + 0.31, 1, ringMat, { inset: 0.02, collar: { depth: 0.03, lip: 0.014, width: 1.3 } }));
262	  zones.tubes.add(buildRingsAt(perfPath, rings05, ringMat, { inset: 0.02, collar }));
263	  const rings0607: number[] = [];
264	  for (let s = s05 + ringPhase; s <= s08 - 1 + 1e-6; s += ringSpacing) if (s >= sGlow05 + 4) rings0607.push(s);
265	  zones.tubes.add(buildRingsAt(perfPath, rings0607, ringMat, { inset: 0.02, collar }));
266	  // copper nozzle lids: one symmetric pair per bay on the side walls a little above eye level,
267	  // skipped where the stream climbs the wall (06 arch) so a lid never blocks the ride
268	  const lidMat = withTubeStrips(withFarGlow(gold({ color: '#ffb27a', roughness: 0.16, emissive: 0.2 }), tubeGlow, 'lid'), { ...strips, color: '#fff0c8', intensity: 2.4 }, 'instance', 'lid');
269	  lidMat.envMap = goldEnv;
270	  lidMat.envMapIntensity = 1.25;
271	  const lidClear = (s: number, centre: THREE.Vector3, size: number) => {
272	    for (let ds = -6; ds <= 6; ds += 1.5) {
273	      const ss = THREE.MathUtils.clamp(s + ds, 0, course.length);
274	      if (course.sample(ss).pos.distanceTo(centre) < size * 1.2 + course.widthAt(ss) / 2 + 1.0) return true;
275	    }
276	    return false;
277	  };
278	  // 05: small round half-dome lids at mid-bay, ≈9° above the axis on both walls (ref 05 §5.5)
279	  const lids05 = rings05.map((s) => s + bay05 / 2).filter((s) => s < sGlow05 - 2);
280	  zones.tubes.add(buildWallLids(perfPath, 0, 0, bay05, lidMat, { positions: lids05, shape: 'dome', angleDeg: 9, droopDeg: 4, size: 1.1, thickness: 0.6, stretch: 1.0, sink: 0.1 }));
