537	function buildPourStream(from: THREE.Vector3, floorY: number, dirX: number) {
538	  const pts: THREE.Vector3[] = [];
539	  const h = from.y - floorY;
540	  for (let i = 0; i <= 16; i++) {
541	    const t = i / 16;
542	    pts.push(new THREE.Vector3(from.x + dirX * 2.2 * t, from.y - h * t * t, from.z));
543	  }
544	  const curve = new THREE.CatmullRomCurve3(pts);
545	  const tex = canvasTexture(64, 256, (c, w, h2) => {
546	    const gr = c.createLinearGradient(0, 0, w, 0);
547	    gr.addColorStop(0, 'rgba(160,240,255,0.15)');
548	    gr.addColorStop(0.5, 'rgba(255,255,255,0.95)');
549	    gr.addColorStop(1, 'rgba(160,240,255,0.15)');
550	    c.fillStyle = gr;
551	    c.fillRect(0, 0, w, h2);
552	    for (let i = 0; i < 40; i++) {
553	      c.fillStyle = 'rgba(255,255,255,0.8)';
554	      c.fillRect(Math.random() * w, Math.random() * h2, 2, 10 + Math.random() * 20);
555	    }
556	  });
557	  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
558	  const mat = new THREE.MeshBasicMaterial({ map: tex, color: '#bff6ff', transparent: true, opacity: 0.85, depthWrite: false, side: THREE.DoubleSide, toneMapped: false });
559	  const mesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 24, 0.32, 8), mat);
560	  return { mesh, update: (t: number) => { tex.offset.y = -t * 2.2; } };
561	}
