378	/** Half-dome wall "lids"/spray heads mounted on the upper tube walls (refs 05–07). */
379	export function buildNozzles(
380	  path: TubePath,
381	  s0: number,
382	  s1: number,
383	  spacing: number,
384	  domeMat: THREE.Material,
385	  rimMat: THREE.Material,
386	  opts: { angleDeg?: number; size?: number } = {},
387	): THREE.Group {
388	  const group = new THREE.Group();
389	  const size = opts.size ?? 1.6;
390	  const dome = new THREE.SphereGeometry(1, 28, 12, 0, Math.PI * 2, 0, Math.PI / 2);
391	  dome.scale(1.25, 0.55, 0.85);
392	  const rim = new THREE.TorusGeometry(1, 0.1, 10, 40);
393	  rim.rotateX(Math.PI / 2);
394	  rim.scale(1.25, 1, 0.85);
395	  const nDomes = Math.floor((s1 - s0) / spacing) + 1;
396	  const imDome = new THREE.InstancedMesh(dome, domeMat, nDomes);
397	  const imRim = new THREE.InstancedMesh(rim, rimMat, nDomes);
398	  const m = new THREE.Matrix4();
399	  const basis = new THREE.Matrix4();
400	  const q = new THREE.Quaternion();
401	  const c = new THREE.Vector3();
402	  const dir = new THREE.Vector3();
403	  let k = 0;
404	  for (let s = s0; s <= s1 && k < nDomes; s += spacing, k++) {
405	    const f = path.frame(s);
406	    const r = path.radius(s);
407	    const side = k % 2 === 0 ? 1 : -1;
408	    const ang = THREE.MathUtils.degToRad(opts.angleDeg ?? 32);
409	    tubeCenterAt(path, s, c);
410	    dir.copy(f.right).multiplyScalar(Math.cos(ang) * side).addScaledVector(f.up, Math.sin(ang)).normalize();
411	    const p = c.clone().addScaledVector(dir, r * 0.985);
412	    const inward = dir.clone().negate();
413	    const xAxis = new THREE.Vector3().crossVectors(inward, f.tan).normalize();
414	    const zAxis = new THREE.Vector3().crossVectors(xAxis, inward).normalize();
415	    basis.makeBasis(xAxis, inward, zAxis);
416	    q.setFromRotationMatrix(basis);
417	    m.compose(p, q, new THREE.Vector3(size, size, size));
418	    imDome.setMatrixAt(k, m);
419	    imRim.setMatrixAt(k, m);
420	  }
421	  imDome.count = imRim.count = k;
422	  imDome.frustumCulled = imRim.frustumCulled = false;
423	  group.add(imDome, imRim);
424	  return group;
425	}
